update media_episode

    media_id = case id

            WHEN #{item.id} THEN #{item.mediaId}

    END,
    season_number = case id

        WHEN #{item.id} THEN #{item.seasonNumber}

    END,
    episode_number = case id

        WHEN #{item.id} THEN #{item.episodeNumber}

    END,
    air_date = case id

        WHEN #{item.id} THEN #{item.airDate}

    END

where
    id in #{item.id}
